package com.aistock.market.alert;
import com.aistock.market.marketlifecycle.*;import com.aistock.common.marketlifecycle.*;import com.aistock.market.version.MarketVersionRepository;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.AtomicReference;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@Tag("mysql") class AlertLocalUseMysqlTest {
 static class Setup {final AlertEvidenceMysqlTest f=new AlertEvidenceMysqlTest();final AtomicReference<Instant> now=new AtomicReference<>(f.now.instant());final Clock clock=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now.get();}};final ObjectMapper json=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);final UUID raw=f.raw(f.bars());final AlertEvidenceRecords.Request request=f.request(raw);final MarketLifecycleService lifecycle=new MarketLifecycleService(f.f.jdbc(),clock,()->true);final MarketEvidenceGate gate=new MarketEvidenceGate(lifecycle,true);final AlertLocalUseOwner uses=new AlertLocalUseOwner(f.f.jdbc(),json,lifecycle,gate,clock,true);final java.util.concurrent.atomic.AtomicInteger calls=new java.util.concurrent.atomic.AtomicInteger();Setup(){f.setupCalendar();}AlertEvidenceService service(AlertEvidenceCollector collector){return new AlertEvidenceService(new MarketVersionRepository(f.f.jdbc()),f.calendar,collector,clock,20,uses);}AlertEvidenceService service(){return service((r,p)->{calls.incrementAndGet();assertFalse(org.springframework.transaction.support.TransactionSynchronizationManager.isActualTransactionActive());assertEquals(1,lifecycle.snapshot("SH600030",raw.toString()).activeUses());return f.candidate(r);});}void replaceHead(){var bars=f.bars().stream().map(b->new com.aistock.market.quotation.RawBar(b.date(),b.open(),b.high(),b.low(),b.close(),b.volumeShares(),b.amountYuan().add(java.math.BigDecimal.ONE),b.tradeStatus(),null)).toList();new com.aistock.market.ingestion.PublicationService(new MarketVersionRepository(f.f.jdbc()),new com.aistock.market.ingestion.CandidateValidator()).publish(new com.aistock.market.ingestion.MarketCandidate(UUID.randomUUID().toString(),"SH600030","SH600030","fixture",true,"ACTIVE","baostock","RAW",clock.instant(),null,"a".repeat(64),bars,List.of(),1L));}MarketLifecycleRecords.Receipt disable(){var state=lifecycle.snapshot("SH600030",raw.toString());return lifecycle.action("SH600030",raw.toString(),UUID.randomUUID().toString(),new MarketUseRecords.Command(UUID.randomUUID().toString(),"DISABLE",state.revision(),"test stop"));}}
 @Test void actualPublishedEvidenceCommitsBeforeReleaseAndReplayDoesNotRecollect(){var s=new Setup();var service=s.service();var done=service.prepare(s.request);assertEquals("AVAILABLE",done.state());assertEquals(1,s.calls.get());assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());var proof=s.uses.proof(s.request.operationId(),"1");assertEquals(9,proof.size());assertEquals(done.evidenceId().toString(),proof.path("resultIdentity").asText());assertEquals(done,service.prepare(s.request));assertEquals(1,s.calls.get());assertEquals(1,s.f.f.jdbc().queryForObject("select count(*) from market_local_alert_use",Integer.class));}
 @Test void blockedOriginalRawNeverReadsBarsOrCollects(){var s=new Setup();s.replaceHead();s.disable();var service=s.service((r,p)->{throw new AssertionError("must not collect blocked raw");});assertEquals("FAILED",service.prepare(s.request).state());assertEquals(0,s.f.f.jdbc().queryForObject("select count(*) from alert_evidence_version",Integer.class));}
 @Test void drainingOriginalUseCanFinishAndThenDisable(){var s=new Setup();s.replaceHead();var done=s.service((r,p)->{assertEquals("DRAINING",s.disable().afterState());return s.f.candidate(r);}).prepare(s.request);assertEquals("AVAILABLE",done.state());assertEquals("DISABLED",s.lifecycle.snapshot("SH600030",s.raw.toString()).useState());}
 @Test void expiredProofPhysicallyStopsPublisherAndCannotReviveAfterClockRollback(){var s=new Setup();var store=new AlertEvidenceStore(s.f.f.jdbc(),s.clock,s.json);assertNull(store.begin(s.request,store.requestHash(s.request)));try(var scope=s.uses.acquire(s.request)){}assertThrows(RuntimeException.class,()->s.uses.proof(s.request.operationId(),"1"));s.now.set(s.request.leaseUntil().plusSeconds(1));var proof=s.uses.proof(s.request.operationId(),"1");assertEquals("FAILED",proof.path("state").asText());s.now.set(s.f.now.instant());assertEquals("FAILED",s.service().prepare(s.request).state());assertEquals(proof,s.uses.proof(s.request.operationId(),"1"));assertEquals(0,s.calls.get());}
 @Test void lostRegistrationRecoversOriginalRequestWithoutRecollect(){var s=new Setup();var spy=spy(s.lifecycle);doAnswer(c->{c.callRealMethod();throw AlertLocalUseOwner.unavailable();}).when(spy).register(anyString(),any(),any(),eq(true));var owner=new AlertLocalUseOwner(s.f.f.jdbc(),s.json,spy,new MarketEvidenceGate(spy,true),s.clock,true);var service=new AlertEvidenceService(new MarketVersionRepository(s.f.f.jdbc()),s.f.calendar,(r,p)->{throw new AssertionError("unknown registration must not collect");},s.clock,20,owner);assertEquals("FAILED",service.prepare(s.request).state());assertEquals(1,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());var original=s.f.f.jdbc().queryForObject("select request_id from market_local_alert_use",String.class);var restored=new AlertLocalUseOwner(s.f.f.jdbc(),s.json,s.lifecycle,s.gate,s.clock,true);restored.recoverOne(s.request.operationId());assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());assertEquals(original,s.f.f.jdbc().queryForObject("select request_id from market_version_use_request",String.class));verify(spy,times(1)).register(anyString(),any(),any(),anyBoolean());assertTrue(s.f.f.jdbc().queryForObject("select completion_acked from market_local_alert_use",Boolean.class));}
 @Test void proofWaitsForActualRowThenReadsClockAndStopsOldWork()throws Exception{var s=new Setup();var store=new AlertEvidenceStore(s.f.f.jdbc(),s.clock,s.json);store.begin(s.request,store.requestHash(s.request));try(var scope=s.uses.acquire(s.request)){}var pool=Executors.newSingleThreadExecutor();try(var lock=s.f.f.jdbc().getDataSource().getConnection()){lock.setAutoCommit(false);try(var q=lock.prepareStatement("select operation_id from alert_evidence_operation where operation_id=? for update")){q.setString(1,s.request.operationId().toString());q.executeQuery().close();}var proof=pool.submit(()->s.uses.proof(s.request.operationId(),"1"));long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);boolean waiting=false;while(System.nanoTime()<end){if(s.f.f.jdbc().queryForObject("select count(*) from performance_schema.data_lock_waits",Integer.class)>0){waiting=true;break;}Thread.sleep(10);}assertTrue(waiting);s.now.set(s.request.leaseUntil().plusSeconds(1));lock.commit();assertEquals("FAILED",proof.get(4,TimeUnit.SECONDS).path("state").asText());assertEquals("FAILED",s.f.f.jdbc().queryForObject("select state from alert_evidence_operation",String.class));}finally{pool.shutdownNow();}}
 @Test void changedOriginalRequestJsonCannotProveOrRelease(){var s=new Setup();var store=new AlertEvidenceStore(s.f.f.jdbc(),s.clock,s.json);store.begin(s.request,store.requestHash(s.request));try(var scope=s.uses.acquire(s.request)){}s.now.set(s.request.leaseUntil().plusSeconds(1));s.f.f.jdbc().update("update market_local_alert_use set original_request_json=json_set(original_request_json,'$.rawVersionId',?)",UUID.randomUUID().toString());assertThrows(RuntimeException.class,()->s.uses.proof(s.request.operationId(),"1"));s.uses.recoverOne(s.request.operationId());assertEquals(1,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());assertFalse(s.f.f.jdbc().queryForObject("select completion_acked from market_local_alert_use",Boolean.class));}

 @Test void expirationDuringPreparationPreventsNewProviderQuery(){
  var s=new Setup();var calendar=spy(s.f.calendar);
  doAnswer(call->{var value=call.callRealMethod();s.now.set(s.request.leaseUntil().plusSeconds(1));return value;}).when(calendar).covering(any(),any());
  var service=new AlertEvidenceService(new MarketVersionRepository(s.f.f.jdbc()),calendar,(r,p)->{s.calls.incrementAndGet();return s.f.candidate(r);},s.clock,20,s.uses);
  var receipt=service.prepare(s.request);
  assertEquals(0,s.calls.get(),"an expired task must not start collection");
  assertEquals("FAILED",receipt.state());
  assertEquals("ATTEMPT_EXPIRED",receipt.errorCode());
  assertEquals(0,s.lifecycle.snapshot("SH600030",s.raw.toString()).activeUses());
 }

}
